import{test}from'node:test';import assert from'node:assert/strict';import fs from'node:fs';
test('global counts validation rejects fabricated, negative, noninteger and unknown counts',async()=>{const p=new URL('../../toolbox-site/assets/usage.js',import.meta.url);assert.ok(fs.existsSync(p),'缺少统计客户端');const{validateSnapshot,rank}=await import(p);const ids=new Set(['a','b','c']);assert.equal(validateSnapshot({schema:1,updatedAt:new Date().toISOString(),counts:{a:4,b:8}},ids).b,8);assert.equal(validateSnapshot({schema:1,counts:{a:-1}},ids),null);assert.equal(validateSnapshot({schema:1,counts:{unknown:12}},ids),null);assert.equal(validateSnapshot({schema:1,counts:{a:1.5}},ids),null);assert.deepEqual(rank(['a','b','c'],{a:4,b:8,c:4}),['b','a','c']);});
